const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jakartaPoint = ee.Geometry.Point(106.8, -6.2);
  const region = jakartaPoint.buffer(20000); // 20 km buffer

  const startYear1 = '1989-01-01';
  const endYear1 = '1989-12-31';

  const startYear2 = '2004-01-01';
  const endYear2 = '2004-12-31';

  const LS_COLLECTION = 'LANDSAT/LT05/C01/SR05'; // Landsat 5 Surface Reflectance

  // Function to mask clouds based on Landsat 5 SR QA_PIXEL band.
  function maskL5sr(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud and cloud shadow, respectively.
    const cloudBit = 1 << 3;
    const cloudShadowBit = 1 << 5;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBit).eq(0).and(
      qa.bitwiseAnd(cloudShadowBit).eq(0)
    );
    return image.updateMask(mask).divide(10000).copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDBI
  function addNdbi(image) {
    const swir1 = image.select('B5');
    const nir = image.select('B4');
    const ndbi = swir1.subtract(nir).divide(swir1.add(nir)).rename('NDBI');
    return image.addBands(ndbi);
  }

  // 2. Data Acquisition & Check
  let collection1 = ee.ImageCollection(LS_COLLECTION)
    .filterBounds(region)
    .filterDate(startYear1, endYear1)
    .map(maskL5sr)
    .map(addNdbi);

  let collection2 = ee.ImageCollection(LS_COLLECTION)
    .filterBounds(region)
    .filterDate(startYear2, endYear2)
    .map(maskL5sr)
    .map(addNdbi);

  const size1 = await collection1.size().getInfo();
  const size2 = await collection2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`1989 Images: ${size1}, 2004 Images: ${size2}`);
    console.log("No images found for one or both periods after initial filtering.");
    console.log("C1");
    return;
  }

  // Create median composites
  const image1 = collection1.median();
  const image2 = collection2.median();

  // 3. Processing (Calculate pixel count to detect C2)
  // Check valid pixels for NDBI band
  const scale = 30; // Landsat resolution
  const reducer = ee.Reducer.count();

  const count1 = await image1.select('NDBI').reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const count2 = await image2.select('NDBI').reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`1989 Images: ${size1}, Valid Pixels: ${count1}`);
    console.log(`2004 Images: ${size2}, Valid Pixels: ${count2}`);
    console.log("No valid pixels remain after cloud masking for one or both periods.");
    console.log("C2");
    return;
  }

  // Classify urban areas using NDBI (NDBI > 0 is often used for urban/built-up areas)
  const urban1 = image1.select('NDBI').gt(0).rename('urban');
  const urban2 = image2.select('NDBI').gt(0).rename('urban');

  // Calculate area (in square kilometers)
  // Each pixel has an area of (scale * scale) square meters.
  // Convert to km^2 by dividing by 1e6.
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Area in km^2 per pixel

  const urbanArea1 = urban1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('urban').getInfo();

  const urbanArea2 = urban2.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('urban').getInfo();

  // 5. Validation & Final Answer
  if (urbanArea1 === null || urbanArea2 === null || isNaN(urbanArea1) || isNaN(urbanArea2)) {
    console.log(`1989 Urban Area: ${urbanArea1}, 2004 Urban Area: ${urbanArea2}`);
    console.log("Calculation resulted in None/NaN.");
    console.log("C3");
    return;
  }

  console.log(`1989 Images: ${size1}, Valid Pixels: ${count1}`);
  console.log(`2004 Images: ${size2}, Valid Pixels: ${count2}`);
  console.log(`Urban Area 1989: ${urbanArea1.toFixed(2)} km²`);
  console.log(`Urban Area 2004: ${urbanArea2.toFixed(2)} km²`);

  if (urbanArea2 > urbanArea1) {
    console.log("A"); // Yes, urban area increased
  } else {
    console.log("B"); // No, urban area did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
